const templates={contract:{name:'合同到期提醒',desc:'在合同到期前主动跟进续签',field:'距离合同到期',unit:'天',days:30,vars:['员工姓名','仓库名称','合同到期日'],sample:{员工姓名:'张明',仓库名称:'上海一仓',合同到期日:'2026-10-22'},title:'请跟进：{员工姓名}的合同即将到期',body:'{员工姓名}在{仓库名称}的合同将于{合同到期日}到期，请及时联系员工并完成续签评估。'},absence:{name:'连续缺勤提醒',desc:'及时识别并跟进出勤异常',field:'连续缺勤达到',unit:'天',days:3,vars:['员工姓名','仓库名称','连续缺勤天数'],sample:{员工姓名:'陈嘉',仓库名称:'上海一仓',连续缺勤天数:'3'},title:'请核实：{员工姓名}连续缺勤',body:'{员工姓名}已连续缺勤{连续缺勤天数}天，请核实原因并提交跟进结果。'},probation:{name:'试用期到期提醒',desc:'提前安排转正评估',field:'距离试用期到期',unit:'天',days:7,vars:['员工姓名','仓库名称','试用期到期日'],sample:{员工姓名:'李悦',仓库名称:'上海一仓',试用期到期日:'2026-09-29'},title:'请安排：{员工姓名}的转正评估',body:'{员工姓名}的试用期将于{试用期到期日}结束，请安排评估并登记结果。'},training:{name:'带教提醒',desc:'跟进未完成带教事项',field:'未完成带教人数达到',unit:'人',days:1,vars:['未完成带教人数','未完成带教前10人员名单'],sample:{未完成带教人数:'3','未完成带教前10人员名单':'肖雷雷1(zt000001)，洛杉矶1号仓-入库组\n肖雷雷2(zt000002)，洛杉矶1号仓-上架组'},title:'请处理：{未完成带教人数}名员工的带教',body:'{未完成带教人数}名员工带教未完成，请及时处理\n{未完成带教前10人员名单}'}};
function fresh(t='contract'){let a=templates[t];let d={id:null,name:'',template:t,scope:['上海一仓'],types:['正式员工'],days:a.days,time:'09:00',recipients:['对应组长'],people:[],channels:['站内','飞书'],mode:'single',repeat:'once',interval:3,fallback:true,title:a.title,body:a.body,status:'草稿'};if(t==='training')d.groups=[[{field:'need',op:'等于',value:'是',unit:''},{field:'done',op:'等于',value:'否',unit:''},{field:'days',op:'大于等于',value:'14',unit:'天'}]];return d}
let rules;try{rules=JSON.parse(localStorage.getItem('hrone-reminders-v1'))}catch{}if(!Array.isArray(rules))rules=[{...fresh(),id:1,name:'华东仓库 · 合同到期提前提醒',status:'已启用',scope:['上海一仓','杭州二仓'],people:['林晓 · HR'],recipients:['对应组长','指定人员']},{...fresh('absence'),id:2,name:'连续缺勤 3 天 · 异常跟进',status:'已启用',channels:['站内','邮件'],recipients:['对应仓长'],repeat:'interval'},{...fresh('probation'),id:3,name:'试用期到期 · 转正评估',status:'草稿',channels:['站内']},{...fresh(),id:4,name:'苏州仓 · 合同续签提醒',status:'已停用',scope:['苏州三仓'],channels:['邮件']}];
let draft=fresh(),view='rules',selectedRule=null,filter='全部',query='',channel='站内',lastField='body',inboxTab='待处理',read=false,done=false,retried=false,logFilter='全部',listFilters={template:'',scope:[],channel:'',time:'',status:''},filterOpen=true,advancedOpen=false,filterScheme='标准方案';const persist=()=>localStorage.setItem('hrone-reminders-v1',JSON.stringify(rules));function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3000)}function badge(s){return `<span class="badge ${s==='草稿'||s==='待处理'?'orange':s==='已停用'?'gray':s==='发送失败'?'red':''}">${s}</span>`}function heading(title,sub,actions=''){return `<div class="eyebrow">人事服务 / 消息提醒</div><div class="heading"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`}function nav(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='rules')renderRules();if(v==='logs')renderLogs();if(v==='inbox')renderInbox();window.scrollTo(0,0)}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>leave(()=>nav(b.dataset.view)));function leave(fn){if(view==='edit')modal('离开当前配置？','未保存的修改将丢失。你可以继续编辑并保存草稿。','离开配置',fn);else fn()}
function listMatches(r){const text=(r.name||'').toLowerCase();return (filter==='全部'||r.status===filter)&&text.includes(query.trim().toLowerCase())&&(!listFilters.template||r.template===listFilters.template)&&(!listFilters.scope.length||listFilters.scope.some(x=>r.scope.includes(x)))&&(!listFilters.channel||r.channels.includes(listFilters.channel))&&(!listFilters.time||r.time===listFilters.time)&&(!listFilters.status||r.status===listFilters.status)}
function activeListFilterCount(){return Object.values(listFilters).filter(Boolean).length}
function listOrgLeaves(n){return [n.name,...(n.children?n.children.flatMap(listOrgLeaves):[])]}
let listOrgOpen=false,listOrgQuery='',listOrgCollapsed=new Set(),listOrgNodes=[];
function listOrgPicker(){return `<div class="org-filter-picker"><button type="button" class="org-filter-trigger" aria-expanded="${listOrgOpen}" onclick="toggleListOrg()"><span>${listFilters.scope.length?`已选 ${listFilters.scope.length} 个组织`:'请选择组织'}</span><span>⌄</span></button><div class="org-filter-dropdown" ${listOrgOpen?'':'hidden'}><input placeholder="搜索组织名称" aria-label="搜索组织" value="${esc(listOrgQuery)}" oninput="listOrgQuery=this.value;renderListOrgTree()"><div id="listOrgTree"></div><div class="org-filter-footer"><span>${listFilters.scope.length?'已选择 '+listFilters.scope.length+' 个组织':''}</span><button onclick="listFilters.scope=[];renderListOrgTree();renderRules()">清空</button><button onclick="toggleListOrg()">完成</button></div></div></div>`}
function toggleListOrg(){listOrgOpen=!listOrgOpen;renderRules();if(listOrgOpen){setTimeout(()=>{renderListOrgTree();document.querySelector('.org-filter-dropdown input')?.focus()},0)}}
function renderListOrgTree(){const box=$('#listOrgTree');if(!box)return;let i=0;listOrgNodes=[];const draw=(n,d,ancestor=false)=>{const match=ancestor||n.name.includes(listOrgQuery);if(listOrgQuery&&!match&&!listOrgLeaves(n).some(x=>x.includes(listOrgQuery)))return '';const id=i++;listOrgNodes.push({id,n});const leaves=listOrgLeaves(n),selected=leaves.filter(x=>listFilters.scope.includes(x)).length;return `<div class="org-tree-row" style="padding-left:${d*18}px">${n.children?`<button class="org-expand" onclick="toggleListOrgBranch('${n.name}')">${listOrgCollapsed.has(n.name)?'▸':'▾'}</button>`:'<span class="org-spacer"></span>'}<label><input type="checkbox" ${selected===leaves.length?'checked':''} ${selected?'data-partial="true"':''} onchange="selectListOrgNode(${id},this.checked)"><span>${esc(n.name)}</span></label></div>${n.children&&(!listOrgCollapsed.has(n.name)||listOrgQuery)?n.children.map(c=>draw(c,d+1,match)).join(''):''}`};box.innerHTML=orgHierarchy.map(n=>draw(n,0)).join('')||'<p class="hint">未找到匹配的组织</p>';for(const input of box.querySelectorAll('input[data-partial]')){if(!input.checked)input.indeterminate=true}}
function toggleListOrgBranch(name){listOrgCollapsed.has(name)?listOrgCollapsed.delete(name):listOrgCollapsed.add(name);renderListOrgTree()}
function selectListOrgNode(id,on){const n=listOrgNodes.find(x=>x.id===id)?.n;if(!n)return;const leaves=listOrgLeaves(n);listFilters.scope=on?[...new Set([...listFilters.scope,...leaves])]:listFilters.scope.filter(x=>!leaves.includes(x));renderListOrgTree();renderRules()}
function renderListFilters(){return `<div class="list-filter-panel"><div class="filter-panel-head"><h2>⌕ 查询条件</h2><div class="scheme-actions"><select aria-label="查询方案" onchange="filterScheme=this.value"><option>标准方案</option><option>我的方案</option></select><button class="scheme-icon" aria-label="保存查询方案" title="保存查询方案" onclick="toast('查询方案已保存')">▣</button><button class="scheme-icon" aria-label="设置查询方案" title="设置查询方案" onclick="toast('查询方案设置已打开')">⚙</button><button class="scheme-icon" aria-label="删除查询方案" title="删除查询方案" onclick="toast('标准方案不可删除')">♜</button></div></div>${filterOpen?`<div class="filter-panel-body"><div class="filter-grid"><label>状态<select onchange="listFilters.status=this.value"><option value="">请选择状态</option>${['已启用','草稿','已停用'].map(x=>`<option ${listFilters.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>规则名称<input value="${esc(query)}" placeholder="请输入规则名称" oninput="query=this.value"></label><label>消息模板<select onchange="listFilters.template=this.value"><option value="">请选择模板</option>${Object.entries(templates).map(([k,t])=>`<option value="${k}" ${listFilters.template===k?'selected':''}>${t.name}</option>`).join('')}</select></label><label>适用组织${listOrgPicker()}</label>${advancedOpen?`<label>推送渠道<select onchange="listFilters.channel=this.value"><option value="">请选择渠道</option>${['站内','飞书','邮件'].map(x=>`<option ${listFilters.channel===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}</div><div class="filter-bottom-row"><div class="filter-advanced"><button class="advanced-toggle" onclick="advancedOpen=!advancedOpen;renderRules()">⚙ ${advancedOpen?'隐藏高级筛选':'显示高级筛选'}</button></div><div class="filter-actions"><button onclick="resetListFilters()">↻ 重置</button><button class="primary" onclick="renderRules()">⌕ 查询</button></div></div></div>`:''}</div>`}
function renderRules(){let list=rules.filter(listMatches);$('#main').innerHTML=`<div class="list-page-actions"></div><div class="panel list-filter-wrap">${renderListFilters()}</div><div class="panel rules-panel"><div class="toolbar"><div></div><div class="toolbar-actions"><button class="primary" onclick="edit()">＋ 新建提醒规则</button></div></div><div id="rows">${ruleTable(list)}</div></div><p class="rule-note">ⓘ 系统按规则定时检查数据；暂停规则后不再产生新的提醒，历史发送记录仍可查看。</p>`}
function resetListFilters(){listFilters={template:'',scope:[],channel:'',time:'',status:''};query='';filterOpen=false;advancedOpen=false;renderRules()}
function renderRows(){$('#rows').innerHTML=ruleTable(rules.filter(listMatches))}
function ruleTable(list){return `<div class="rule-table-scroll"><table class="reminder-rule-table"><thead><tr>${['规则名称','消息模板','状态','适用组织','触发条件','发送对象','通知时机','推送渠道','操作'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${list.map(r=>{const condition=r.groups?r.groups.map(g=>'（'+g.map(x=>(conditionFields[r.template].find(f=>f[0]===x.field)?.[1]||x.field)+x.op+x.value).join(' 且 ')+'）').join(' 或 '):templates[r.template].field+' '+r.days+' 天'+(r.template==='absence'?'及以上':'以内');const recipients=r.recipients.map(x=>x==='对应组长'?'组长':x==='对应仓长'?'仓长/职能主管':x);return `<tr><td><button class="rule-name-link" onclick="edit(${r.id})">${esc(r.name)}</button></td><td><span class="template-cell">${templates[r.template].name}</span></td><td>${badge(r.status)}</td><td><div class="cell-wrap">${esc(r.scope.join('、'))||'未选择组织'}</div></td><td><div class="condition-cell" title="${esc(condition)}">${esc(condition)||'尚未配置条件'}</div>${r.groups?`<small>${r.groups.length} 组 · ${r.groups.reduce((n,g)=>n+g.length,0)} 条条件</small>`:''}</td><td><div class="cell-wrap">${esc(recipients.filter(x=>x!=='指定人员').join('、'))}</div>${recipients.includes('指定人员')?`<small>指定人员：${esc(r.people.join('、'))||'未选择'}</small>`:''}</td><td><div>${r.schedule==='weekly'?'每周 '+esc((r.weekdays||[]).join('、')):'每天'}</div><strong class="time-label">${esc(r.time)||'未设置时间'}</strong></td><td><div class="channel-tags">${r.channels.map(c=>`<span>${c}</span>`).join('')}</div></td><td><div class="row-actions"><button class="icon" title="编辑消息提醒" aria-label="编辑 ${esc(r.name)}" onclick="edit(${r.id})">✎</button><button class="icon rule-toggle" title="${r.status==='已启用'?'停用规则':'启用规则'}" aria-label="${r.status==='已启用'?'停用':'启用'} ${esc(r.name)}" onclick="toggleRule(${r.id})">${r.status==='已启用'?'Ⅱ':'▷'}</button><button class="icon copy-rule" title="复制规则" aria-label="复制 ${esc(r.name)}" onclick="copyRule(${r.id})">⧉</button></div></td></tr>`}).join('')}</tbody></table></div>${list.length?'':'<div class="empty">未找到符合条件的规则，请调整筛选或搜索词。</div>'}<div class="foot pagination"><button class="page-arrow disabled" aria-label="上一页">‹</button><button class="page-number active">1</button><button class="page-arrow disabled" aria-label="下一页">›</button><select class="page-size" aria-label="每页条数"><option>20 条/页</option></select><span class="jump-label">跳至</span><input class="page-input" aria-label="跳转页码" value="1"><span>页</span></div>`}

function closeOtherRowMenus(current){if(!current.open)return;document.querySelectorAll('.row-more[open]').forEach(d=>{if(d!==current)d.open=false})}
function toggleRule(id){let r=rules.find(x=>x.id===id);if(r.status!=='已启用'){edit(id);saveRule(true);return}modal('停用这条提醒规则？','停用后将停止后续检查和发送，已发送的消息与处理记录会保留。','确认停用',()=>{r.status='已停用';persist();renderRules();toast('规则已停用')})}function copyRule(id){draft=structuredClone(rules.find(r=>r.id===id));draft.id=null;draft.name+='（副本）';draft.status='草稿';showEditor()}
function edit(id){draft=id?structuredClone(rules.find(r=>r.id===id)):fresh();showEditor()}function checks(key,items){return `<div class="choices">${items.map(v=>`<label class="choice"><input type="checkbox" ${draft[key].includes(v)?'checked':''} onchange="changeArray('${key}','${v}',this.checked)">${v}</label>`).join('')}</div>`}function radios(key,items){return `<div class="choices">${items.map(([val,label])=>`<label class="choice"><input type="radio" name="${key}" value="${val}" ${draft[key]===val?'checked':''} onchange="changeValue('${key}',this.value)">${label}</label>`).join('')}</div>`}function changeArray(k,v,on){draft[k]=on?[...draft[k],v]:draft[k].filter(x=>x!==v);if(k==='channels'&&!draft.channels.includes(channel))channel=draft.channels[0]||'站内';if(k==='recipients'||k==='channels')renderEditor();else updatePreview()}function changeValue(k,v){draft[k]=v;if(k==='mode'){let a=templates[draft.template];draft.title=v==='summary'?'请跟进：{仓库名称}有{命中人数}人需处理':a.title;draft.body=v==='summary'?'以下人员已达到提醒条件，请逐一跟进并登记处理结果。\n{人员明细}':a.body;resetChannelContent();renderEditor()}else if(k==='repeat')renderEditor();else updatePreview()}
function showEditor(){view='edit';channel=draft.channels[0]||'站内';ensureChannelContent();draft.title=draft.channelContent[channel].title;draft.body=draft.channelContent[channel].body;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='rules'));renderEditor();window.scrollTo(0,0)}function renderEditor(){
 ensureChannelContent();ensureRuleControls();
 const t=templates[draft.template],scroll=$('.settings-column')?.scrollTop||0;
 $('#main').innerHTML=`<div class="editor-top"><div><h1>${draft.id?'编辑消息提醒':'新建消息提醒'}</h1><span>消息提醒配置中心 <i>/</i> 完整编辑器</span></div><button class="close-editor" onclick="leave(()=>nav('rules'))">× 关闭</button></div><div id="errors" role="alert"></div>
 <div class="editor editor-v2"><div class="settings-column">
 <section class="form-section"><div class="section-title"><span class="number">1</span><h2>基本信息</h2></div><div class="field"><label for="ruleName"><span class="required">*</span> 规则名称</label><input id="ruleName" maxlength="60" value="${esc(draft.name)}" placeholder="请输入规则名称" oninput="draft.name=this.value;$('#errors').innerHTML=''"></div><div class="field"><label for="templateSelect">消息模板</label><select id="templateSelect" onchange="const next=this.value;this.value=draft.template;switchTemplate(next)">${Object.entries(templates).map(([k,v])=>`<option value="${k}" ${draft.template===k?'selected':''}>${v.name}</option>`).join('')}</select></div><div class="field"><label><span class="required">*</span> 适用组织</label>${orgPicker()}</div></section>
 <section class="form-section"><div class="section-title"><span class="number">2</span><h2>触发条件</h2></div>${conditionEditor()}</section>
 <section class="form-section"><div class="section-title"><span class="number">3</span><h2>发送对象</h2></div><div class="recipient-options">${['组长','仓长/职能主管','指定人员'].map(v=>`<label class="recipient-row"><input type="checkbox" ${draft.recipients.includes(v)?'checked':''} onchange="changeArray('recipients','${v}',this.checked)"><span>${v}</span></label>`).join('')}</div>${draft.recipients.includes('指定人员')?peoplePicker():''}<p class="hint">同一接收人自动去重，接收角色或账号缺失时自动跳过</p></section>
 <section class="form-section"><div class="section-title"><span class="number">4</span><h2>通知时机</h2></div><div class="timing-row"><select aria-label="通知周期" onchange="draft.schedule=this.value;renderEditor()"><option value="daily" ${draft.schedule==='daily'?'selected':''}>每天</option><option value="weekly" ${draft.schedule==='weekly'?'selected':''}>每周</option></select>${draft.schedule==='weekly'?`<div class="weekday-options">${['周一','周二','周三','周四','周五','周六','周日'].map(d=>`<label><input type="checkbox" ${draft.weekdays.includes(d)?'checked':''} onchange="toggleWeek('${d}',this.checked)"><span>${d}</span></label>`).join('')}</div>`:''}</div><div class="inline" style="margin-top:12px">通知时间 <input type="time" aria-label="发送时间" value="${draft.time}" oninput="draft.time=this.value;updatePreview()"><span class="hint">区域时间</span></div><p class="hint">启用后在下一个设定时点检查条件并发送。</p></section>
 <section class="content-column"><div class="section-title"><span class="number">5</span><h2>推送渠道与消息内容</h2></div><div class="channel-editor-tabs" role="tablist" aria-label="渠道内容配置">${['站内','飞书','邮件'].map(c=>`<button role="tab" aria-selected="${channel===c}" class="${channel===c?'selected':''}" onclick="selectContentChannel('${c}')">${c}<small>${draft.channels.includes(c)?'已启用':'未启用'}</small></button>`).join('')}</div><div class="channel-enable"><label><input type="checkbox" aria-label="启用当前渠道" ${draft.channels.includes(channel)?'checked':''} onchange="setChannelEnabled(this.checked)">启用${channel}通知</label><span>标题、正文与操作按钮按渠道独立保存</span></div><div class="variable-toolbox"><h3><span>〈/〉</span> 变量工具箱 <small>点击插入到光标位置</small></h3><div class="choices">${(draft.mode==='summary'?['仓库名称','命中人数','人员明细']:t.vars).map(v=>`<button class="variable" onmousedown="event.preventDefault()" onclick="insertVar('${v}')">{${v}}</button>`).join('')}</div><p class="hint">仅显示当前模板和发送方式支持的变量。</p></div><div class="field"><label for="titleInput"><span class="required">*</span> 消息标题</label><input id="titleInput" maxlength="100" value="${esc(draft.title)}" onfocus="lastField='title'" oninput="draft.title=this.value;updatePreview();focusChannelPreview()"></div><div class="field body-field"><label for="bodyInput"><span class="required">*</span> 消息内容</label><div class="body-editor"><textarea id="bodyInput" onfocus="lastField='body'" oninput="draft.body=this.value;updatePreview();focusChannelPreview()">${esc(draft.body)}</textarea></div><div class="editor-meta"><span>右侧显示消息预览效果</span><span id="charCount">${draft.body.length} 字</span></div></div>${renderActionSettings()}<div class="content-note">ⓘ 变量会在发送时替换为实际业务数据。预览使用示例人员，消息不会实际发送。</div></section></div>
 <div class="preview-column"><div class="preview" id="preview"></div></div></div><footer class="editor-footer"><span>规则负责人：林晓 <i>·</i> ${draft.id?'正在编辑已保存规则':'尚未保存'}</span><div class="actions"><button onclick="leave(()=>nav('rules'))">× 取消</button><button onclick="saveRule(false)">▣ 保存草稿</button><button class="primary" onclick="saveRule(true)">✓ 保存并启用</button></div></footer>`;
 $('.settings-column').scrollTop=scroll;if(orgOpen)renderOrgTree();updatePreview();
}
function formatBody(kind){const el=$('#bodyInput'),a=el.selectionStart,b=el.selectionEnd,selection=el.value.slice(a,b);const replacement=kind==='list'?'\n• '+(selection||'列表内容'):kind==='bold'?'**'+(selection||'加粗内容')+'**':'*'+(selection||'斜体内容')+'*';draft.body=el.value.slice(0,a)+replacement+el.value.slice(b);el.value=draft.body;el.focus();el.setSelectionRange(a,a+replacement.length);lastField='body';updatePreview()}
function templateDefaultGroups(k){if(k==='training')return [[{field:'need',op:'等于',value:'是',unit:''},{field:'done',op:'等于',value:'否',unit:''},{field:'days',op:'大于等于',value:'14',unit:'天'}]];return [[defaultCondition()]]}function switchTemplate(k){if(k===draft.template)return;modal('切换消息模板？','触发天数和通知文案将替换为新模板默认值，其他配置保留。','确认切换',()=>{draft.template=k;draft.days=templates[k].days;draft.groups=templateDefaultGroups(k);draft.mode='single';draft.title=templates[k].title;draft.body=templates[k].body;resetChannelContent();renderEditor()})}function insertVar(v){let input=$(lastField==='title'?'#titleInput':'#bodyInput');let start=input.selectionStart,end=input.selectionEnd;draft[lastField]=draft[lastField].slice(0,start)+'{'+v+'}'+draft[lastField].slice(end);input.value=draft[lastField];input.focus();input.setSelectionRange(start+v.length+2,start+v.length+2);updatePreview()}
