function validate(){syncChannel();let e=[];if(!draft.name.trim())e.push('请填写规则名称');if(!draft.scope.length)e.push('请至少选择一个适用组织');if(draft.schedule==='weekly'&&!draft.weekdays.length)e.push('请选择每周的通知日期');if(!draft.groups.length)e.push('请至少添加一条触发条件');for(const g of draft.groups)for(const r of g){if(!String(r.value).trim())e.push('请填写条件值');if(conditionFields[draft.template].find(f=>f[0]===r.field)?.[2]==='number'&&(!Number.isFinite(Number(r.value))||Number(r.value)<0))e.push('数字条件值须为非负数');}if(!draft.time)e.push('请设置通知时间');if(!draft.recipients.length)e.push('请至少选择一种通知对象');if(draft.recipients.includes('指定人员')&&!draft.people.length)e.push('请选择指定接收人员');if(!draft.channels.length)e.push('请至少选择一个通知渠道');let allowed=draft.mode==='summary'?['仓库名称','命中人数','人员明细']:templates[draft.template].vars;let unknown=[...new Set([...(`${draft.title}${draft.body}`).matchAll(/\{([^}]+)\}/g)].map(x=>x[1]).filter(v=>!allowed.includes(v)))];for(const c of draft.channels){const m=draft.channelContent[c];if(!m.title.trim()||!m.body.trim())e.push(c+'：请填写标题和正文');const bad=[...(`${m.title}${m.body}`).matchAll(/\{([^}]+)\}/g)].map(x=>x[1]).filter(v=>!allowed.includes(v));if(bad.length)e.push(c+'：不支持的变量 '+bad.join('、'));for(const a of Object.values(m.actions))if(a.enabled){if(!a.label.trim())e.push(c+'：请填写操作按钮名称');if(a.label.length>10)e.push(c+'：按钮名称最多10个字');}}return e}function saveRule(enable){syncChannel();let e=enable?validate():(!draft.name.trim()?['请填写规则名称后保存草稿']:[]);if(e.length){$('#errors').innerHTML=`<div class="error">${e.map(esc).join('；')}</div>`;window.scrollTo(0,0);$('#ruleName').focus();$('.settings-column')?.scrollTo(0,0);return}const commit=()=>{draft.status=enable?'已启用':'草稿';if(!draft.id){draft.id=Date.now();rules.unshift(structuredClone(draft))}else rules[rules.findIndex(r=>r.id===draft.id)]=structuredClone(draft);persist();nav('rules');toast(enable?'规则已启用，将在下一个设定时点执行':'草稿已保存，可稍后继续编辑')};if(enable)modal('确认启用提醒规则',`“${draft.name}”将于${scheduleText()}自动检查并发送。当前为交互演示，所有发送均为模拟。`,'确认启用',commit);else commit()}
let restoreFocus;function modal(title,body,label,action,html=''){restoreFocus=document.activeElement;$('#dialog').innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p>${html}<div class="dialog-actions"><button id="cancelDialog">← 返回</button><button class="primary" id="confirmDialog">✓ ${esc(label)}</button></div>`;$('#cancelDialog').onclick=closeModal;$('#confirmDialog').onclick=()=>{closeModal();action()};$('#dialog').showModal();$('#cancelDialog').focus()}function closeModal(){$('#dialog').close();restoreFocus?.focus()}$('#dialog').addEventListener('cancel',()=>setTimeout(()=>restoreFocus?.focus(),0));function trial(){let e=validate();if(e.length){toast('模拟前请完善配置：'+e[0]);return}modal('模拟检查 · 示例接收结果','以下是固定示例数据，用于评审接收人解析与异常展示，并非真实业务计算。','完成查看',()=>{},`<div class="detail-grid"><div><span>规则范围</span><br>${esc(draft.scope.join('、'))}</div><div><span>接收对象</span><br>${esc(draft.recipients.join('、'))}</div><div><span>展示样本</span><br>张明、李悦、陈嘉</div><div><span>发送形式</span><br>${draft.mode==='summary'?'按接收人和仓库汇总':'逐人发送'}</div></div><div class="warn">异常样例：李悦未配置组长，该接收对象自动跳过，其余有效接收人继续发送。</div>`)}
