function renderLogs(){let entries=[['09:00:12','华东仓库 · 合同到期提前提醒','张明 → 刘海 · 组长','飞书','已送达'],['09:00:10','连续缺勤 3 天 · 异常跟进','陈嘉 → 赵磊 · 仓长','邮件',retried?'已送达':'发送失败'],['09:00:08','华东仓库 · 合同到期提前提醒','李悦 → 林晓 · HR（兜底）','站内','已送达']].filter(r=>(!selectedRule||r[1]===(rules.find(x=>x.id===selectedRule)?.name||r[1]))&&(logFilter==='全部'||r[4]===logFilter));const ruleTitle=selectedRule?(rules.find(x=>x.id===selectedRule)?.name||'规则执行记录'):'执行记录';$('#main').innerHTML=heading(ruleTitle,'查看这条消息提醒规则的检查、发送与异常处理记录。',selectedRule?'<button onclick="selectedRule=null;renderLogs()">查看全部记录</button>':'')+`<div class="info">◷ 最近检查：2026-09-22 09:00（示例） · 系统自动检查 → 匹配规则 → 解析对象 → 按渠道发送</div><div class="panel"><div class="toolbar"><div class="tabs">${['全部','已送达','发送失败'].map(x=>`<button class="${logFilter===x?'selected':''}" onclick="logFilter='${x}';renderLogs()">${x}</button>`).join('')}</div><span class="sub">2026-09-22 · 示例批次</span></div><table><thead><tr><th>执行时间</th><th>提醒规则</th><th>业务人员 → 接收人</th><th>渠道</th><th>结果</th><th>操作</th></tr></thead><tbody>${entries.map(r=>`<tr>${r.slice(0,4).map(c=>`<td>${c}</td>`).join('')}<td>${badge(r[4])}</td><td><button class="icon" title="查看执行详情" aria-label="查看执行详情" onclick="logDetail(${r[3]==='邮件'})">↗</button></td></tr>`).join('')}</tbody></table>${entries.length?'':'<div class="empty">当前没有发送失败的记录。</div>'}</div><p class="rule-note">失败渠道可单独重试，已送达渠道不重复发送；角色缺失按规则中的兜底方式处理。</p>`}
function logDetail(email){if(email&&!retried){modal('发送失败 · 接收人缺少邮箱','负责人：林晓 · HR。请补齐赵磊的邮箱后，重试当前失败渠道。','模拟补齐并重试',()=>{retried=true;renderLogs();toast('邮件模拟重试成功，处理结果已记录')},'<div class="detail-grid"><div><span>业务人员</span><br>陈嘉 · 上海一仓</div><div><span>接收人</span><br>赵磊 · 仓长</div><div><span>失败渠道</span><br>邮件</div><div><span>其他渠道</span><br>站内已送达，不重复发送</div></div>')}else modal('执行详情 · 已送达',email?'林晓已模拟补齐邮箱并重试成功，2026-09-22 09:05。':'系统已按规则完成发送。查看消息不会自动完成业务跟进。','完成查看',()=>{},'<div class="detail-grid"><div><span>触发方式</span><br>定时检查命中</div><div><span>执行状态</span><br>已完成发送</div></div>')}
function renderInbox(){$('#main').innerHTML=heading('接收效果','组长刘海的站内消息示例 · 已读状态与业务处理状态分别记录。')+`<div class="info">当前演示角色：刘海 · 上海一仓组长。职责：联系员工、评估续签并登记跟进结果。</div><div class="panel"><div class="toolbar"><div class="tabs">${['待处理','已完成'].map(t=>`<button class="${inboxTab===t?'selected':''}" onclick="inboxTab='${t}';renderInbox()">${t} ${t==='待处理'?(done?0:1):(done?1:0)}</button>`).join('')}</div><span class="sub">未读消息 ${read?0:1} · 待处理事项 ${done?0:1}</span></div>${(inboxTab==='待处理'&&!done)||(inboxTab==='已完成'&&done)?`<div style="padding:28px"><div class="inline">${badge(done?'已完成':'待处理')}<span class="sub">2026-09-22 09:00 · 合同到期提醒 · ${read?'已读':'未读'}</span></div><h2 style="margin:18px 0 10px">请跟进：张明的合同即将到期</h2><p style="font-size:13px;color:#7d8ba0">张明在上海一仓的合同将于 2026-10-22 到期，请及时联系员工并完成续签评估。</p><div class="detail-grid"><div><span>处理责任人</span><br>刘海 · 组长</div><div><span>完成条件</span><br>登记续签评估结果</div></div><div class="actions" style="margin-top:20px">${!done?`<button onclick="read=true;renderInbox();toast('已标为已读，事项仍保留在待处理')">✓ 标为已读</button><button class="primary" onclick="handleTask()">✎ 登记跟进结果</button>`:`<p class="sub">刘海 · 2026-09-22 10:15 · 评估结果：${esc(window.outcome||'建议续签')}<br>处理记录已保留，同一业务记录停止后续提醒。</p>`}</div></div>`:'<div class="empty">'+(inboxTab==='待处理'?'当前没有待处理事项，历史结果可在已完成中查看。':'暂无已完成记录，完成跟进后将在这里保留。')+'</div>'}</div>`}function handleTask(){read=true;renderInbox();modal('登记合同跟进结果','提交后移入已完成记录，并停止这份合同的后续提醒。','提交处理结果',()=>{window.outcome=$('input[name=outcome]:checked').value;done=true;renderInbox();toast('跟进已完成，记录已移入「已完成」')},'<div class="choices"><label class="choice"><input type="radio" name="outcome" value="建议续签" checked>建议续签</label><label class="choice"><input type="radio" name="outcome" value="不建议续签">不建议续签</label></div>')}
function ensureChannelContent(){if(draft.template==='training'&&draft.title==='请处理：{未完成带教人数}名员工的带教卡片')draft.title=templates.training.title;if(!draft.channelContent)draft.channelContent={};for(const c of ['站内','飞书','邮件'])if(!draft.channelContent[c])draft.channelContent[c]={title:draft.title,body:draft.body,actions:{view:{enabled:true,label:'查看详情'},download:{enabled:false,label:'下载附件'}}};for(const c of ['站内','飞书','邮件'])if(draft.template==='training'&&draft.channelContent[c].title==='请处理：{未完成带教人数}名员工的带教卡片')draft.channelContent[c].title=templates.training.title;draft.channelContent['邮件'].actions.view.enabled=false;}
