function previewAction(c,key){if(key==='view'){modal(c+' · 查看详情','这是当前模板关联的示例业务详情。实际发送时打开对应人员的业务记录。','完成查看',()=>{},`<div class="detail-grid"><div>员工<br>张明</div><div>仓库<br>${esc(draft.scope[0]||'上海一仓')}</div><div>业务场景<br>${templates[draft.template].name}</div><div>处理责任人<br>刘海 · 组长</div></div>`)}else{const blob=new Blob(['HRONE 消息提醒 · 示例附件\n渠道：'+c+'\n业务场景：'+templates[draft.template].name+'\n员工：张明\n仅供原型评审，非真实业务数据。'],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='消息提醒-示例附件.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('示例附件已下载');}}
