let orgOpen=false,orgCollapsed=new Set(),orgQuery='';
function orgLeaves(n){return n.children?n.children.flatMap(orgLeaves):[n.name]}
function orgPicker(){return `<div class="org-picker"><button type="button" id="orgTrigger" class="org-trigger" aria-expanded="${orgOpen}" onclick="toggleOrg()"><span>${draft.scope.length?draft.scope.map(esc).join('、'):'请选择适用组织'}</span><span>⌄</span></button><div id="orgDropdown" ${orgOpen?'':'hidden'}><input id="orgSearch" aria-label="搜索组织" placeholder="搜索组织名称" value="${esc(orgQuery)}" oninput="orgQuery=this.value;renderOrgTree()"><div id="orgTree"></div><div class="org-footer"><span id="orgCount"></span><button onclick="draft.scope=[];renderOrgTree();updatePreview();updateOrgLabel()">× 清空</button><button onclick="closeOrg()">✓ 完成</button></div></div></div>`}
function toggleOrg(){orgOpen=!orgOpen;$('#orgDropdown').hidden=!orgOpen;$('#orgTrigger').setAttribute('aria-expanded',String(orgOpen));if(orgOpen){renderOrgTree();$('#orgSearch').focus()}else $('#orgTrigger').focus()}
function closeOrg(){orgOpen=false;if($('#orgDropdown'))$('#orgDropdown').hidden=true;$('#orgTrigger')?.setAttribute('aria-expanded','false');$('#orgTrigger')?.focus({preventScroll:true})}
function updateOrgLabel(){const s=$('#orgTrigger span');if(s)s.textContent=draft.scope.join('、')||'请选择适用组织'}
function renderOrgTree(){if(!$('#orgTree'))return;let index=0;const nodes=[];const draw=(n,depth,ancestorMatch=false)=>{const match=ancestorMatch||n.name.includes(orgQuery);if(orgQuery&&!match&&!orgLeaves(n).some(x=>x.includes(orgQuery)))return '';const id=index++;nodes.push({id,n});const leaves=orgLeaves(n),num=leaves.filter(x=>draft.scope.includes(x)).length;return `<div class="org-tree-row" style="padding-left:${depth*20}px">${n.children?`<button class="org-expand" aria-label="${orgCollapsed.has(n.name)?'展开':'收起'}${n.name}" onclick="toggleOrgBranch('${n.name}')">${orgCollapsed.has(n.name)?'▸':'▾'}</button>`:'<span class="org-spacer"></span>'}<label><input type="checkbox" data-org-id="${id}" ${num===leaves.length?'checked':''} onchange="selectOrgNode(${id},this.checked)"><span>${esc(n.name)}</span></label></div>${n.children&&(!orgCollapsed.has(n.name)||orgQuery)?n.children.map(c=>draw(c,depth+1,match)).join(''):''}`};$('#orgTree').innerHTML=orgHierarchy.map(n=>draw(n,0)).join('')||'<p class="hint">未找到匹配的组织</p>';window.currentOrgNodes=nodes;for(const {id,n} of nodes){const leaves=orgLeaves(n),num=leaves.filter(x=>draft.scope.includes(x)).length;$('#orgTree input[data-org-id="'+id+'"]').indeterminate=num>0&&num<leaves.length}$('#orgCount').textContent='已选择 '+draft.scope.length+' 个组织'}
function toggleOrgBranch(name){orgCollapsed.has(name)?orgCollapsed.delete(name):orgCollapsed.add(name);renderOrgTree()}
function selectOrgNode(id,on){const leaves=orgLeaves(window.currentOrgNodes.find(x=>x.id===id).n);draft.scope=on?[...new Set([...draft.scope,...leaves])]:draft.scope.filter(x=>!leaves.includes(x));renderOrgTree();updateOrgLabel();updatePreview()}
document.addEventListener('click',e=>{if(orgOpen&&!e.target.closest('.org-picker')){orgOpen=false;if($('#orgDropdown'))$('#orgDropdown').hidden=true;$('#orgTrigger')?.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&orgOpen){e.preventDefault();closeOrg()}});
const start=new URLSearchParams(location.search).get('view');if(start==='edit'){const id=Number(new URLSearchParams(location.search).get('id'));edit(rules.some(r=>r.id===id)?id:undefined);}else nav(start==='logs'?'logs':'rules');
